import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureApp {
    public static void main(String[] args) throws Exception {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/testdb", "user", "password");

        // Use PreparedStatement with parameterized queries to safely handle user input
        String userInput = "1";
        String query = "SELECT * FROM users WHERE id = ?";

        PreparedStatement pstmt = conn.prepareStatement(query);
        pstmt.setString(1, userInput); // Safely bind the user input

